INSERT INTO wine (name, region, variety, vintage, category, image, description, price, stock, threshold) VALUES
('Château Lueur Noire', 'Bordeaux', 'Cabernet Sauvignon', '2018', 'Red', '/assets/wines/chateau-lueur-noire.jpg', '黒系果実の凝縮感に、カカオと杉の香りが重なる重厚な一本。きめ細かなタンニンが長い余韻を形づくります。', 7400.0, 24, 8),
('Monteluna Estate', 'Tuscany', 'Sangiovese', '2019', 'Red', '/assets/wines/monteluna-estate.jpg', '熟したチェリーとドライハーブの香り。伸びやかな酸と穏やかな樽香が、トスカーナらしい温かみを伝えます。', 4600.0, 19, 6),
('Aotearoa Cellars', 'Marlborough', 'Sauvignon Blanc', '2021', 'White', '/assets/wines/aotearoa-cellars.jpg', '瑞々しい柑橘とハーブの香りに凛とした酸が重なり、ミネラルを感じる端正な余韻へと続きます。', 3700.0, 35, 10),
('Valle di Sera', 'Piedmont', 'Nebbiolo', '2017', 'Red', '/assets/wines/valle-di-sera.jpg', '薔薇や赤い果実の香りに、土とスパイスの複雑さ。力強い骨格がほどけながら、優雅な余韻を残します。', 8300.0, 14, 5),
('Moonlight Spark', 'Champagne', 'Champagne Blend', '2020', 'Sparkling', '/assets/wines/moonlight-spark.jpg', '繊細な泡と白い花、焼きたてのブリオッシュの香り。乾杯から食事の終わりまで寄り添う上品な味わいです。', 5900.0, 22, 7),
('Sakura Reserve', 'Yamanashi', 'Koshu', '2020', 'White', '/assets/wines/sakura-reserve.jpg', '白桃と和柑橘の繊細な香り。甲州らしい清らかな酸とほのかな苦みが、料理を引き立てます。', 4300.0, 12, 4);
